-- Phase 16: append-only tenant audit, with no ability for application roles to forge rows.
-- Migration owner only. Apply after 0013. Audit records generated by triggers in the same transaction.
CREATE TABLE IF NOT EXISTS public.audit_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES public.tenants(tenant_id) ON DELETE RESTRICT,
  user_id uuid, -- historical actor identifier; never mutate old audit rows when users are removed
  action text NOT NULL CHECK (action IN ('INSERT','UPDATE','DELETE')),
  entity_type text NOT NULL,
  entity_id uuid NOT NULL,
  old_values jsonb,
  new_values jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT audit_values_check CHECK (
    (action='INSERT' AND old_values IS NULL AND new_values IS NOT NULL)
    OR (action='UPDATE' AND old_values IS NOT NULL AND new_values IS NOT NULL)
    OR (action='DELETE' AND old_values IS NOT NULL AND new_values IS NULL)
  )
);
ALTER TABLE public.audit_logs DROP CONSTRAINT IF EXISTS audit_logs_user_id_fkey;
CREATE INDEX IF NOT EXISTS audit_logs_tenant_created_idx
  ON public.audit_logs(tenant_id,created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS audit_logs_tenant_entity_idx
  ON public.audit_logs(tenant_id,entity_type,entity_id,created_at DESC);

ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.audit_logs FROM PUBLIC,tenant_runtime,auth_runtime;
GRANT SELECT ON public.audit_logs TO tenant_runtime;

-- Refuse to expose audit rows to normal tenant users even if they have the runtime credential.
CREATE OR REPLACE FUNCTION app.can_read_audit() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,app AS $$
 SELECT EXISTS (
   SELECT 1 FROM public.users u
   JOIN public.tenants t ON t.tenant_id=u.tenant_id
   WHERE u.id=NULLIF(current_setting('app.actor_id',true),'')::uuid
     AND u.tenant_id=app.current_tenant_id()
     AND u.role='COMPANY_ADMIN' AND u.is_active AND t.is_active AND NOT t.is_platform_tenant
 );
$$;
REVOKE ALL ON FUNCTION app.can_read_audit() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.can_read_audit() TO tenant_runtime;
DROP POLICY IF EXISTS audit_company_admin_read ON public.audit_logs;
CREATE POLICY audit_company_admin_read ON public.audit_logs FOR SELECT TO tenant_runtime
  USING (tenant_id=(SELECT app.current_tenant_id()) AND (SELECT app.can_read_audit()));

DO $audit_owner$ BEGIN
  EXECUTE format('DROP POLICY IF EXISTS migrations_admin ON public.audit_logs');
  EXECUTE format('CREATE POLICY migrations_admin ON public.audit_logs FOR ALL TO %I USING (true) WITH CHECK (true)',current_user);
END $audit_owner$;

-- A failing audit INSERT aborts the original write. Record actor only if membership matches row tenant.
-- The verified Next.js server sets app.actor_id transaction-locally, never from request bodies.
CREATE OR REPLACE FUNCTION app.audit_business_change() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,app AS $$
DECLARE
  before_row jsonb;
  after_row jsonb;
  row_tenant uuid;
  row_id uuid;
  claimed_actor uuid;
  valid_actor uuid;
BEGIN
  IF TG_OP='DELETE' THEN
    before_row=to_jsonb(OLD); row_tenant=OLD.tenant_id; row_id=OLD.id;
  ELSE
    after_row=to_jsonb(NEW); row_tenant=NEW.tenant_id; row_id=NEW.id;
    IF TG_OP='UPDATE' THEN
      before_row=to_jsonb(OLD);
      IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
        RAISE EXCEPTION 'Audit refuses tenant change' USING ERRCODE='42501';
      END IF;
    END IF;
  END IF;
  -- Remove fields containing private contact details or free-text financial references.
  before_row=before_row - 'phone_primary' - 'phone_secondary' - 'national_id' - 'email'
    - 'customer_phone' - 'customer_name' - 'reference_number' - 'bounced_reason';
  after_row=after_row - 'phone_primary' - 'phone_secondary' - 'national_id' - 'email'
    - 'customer_phone' - 'customer_name' - 'reference_number' - 'bounced_reason';
  -- Preserve the event even when only redacted fields changed.
  claimed_actor=NULLIF(current_setting('app.actor_id',true),'')::uuid;
  IF claimed_actor IS NOT NULL THEN
    SELECT u.id INTO valid_actor FROM public.users u
      WHERE u.id=claimed_actor AND u.tenant_id=row_tenant AND u.is_active;
    IF valid_actor IS NULL THEN
      RAISE EXCEPTION 'Invalid audit actor for tenant' USING ERRCODE='42501';
    END IF;
  END IF;
  INSERT INTO public.audit_logs
    (tenant_id,user_id,action,entity_type,entity_id,old_values,new_values)
    VALUES(row_tenant,valid_actor,TG_OP,TG_TABLE_NAME,row_id,before_row,after_row);
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
REVOKE ALL ON FUNCTION app.audit_business_change() FROM PUBLIC;

-- Triggers are installed idempotently for core business and finance tables.
DO $audit_triggers$
DECLARE table_name text;
BEGIN
  FOREACH table_name IN ARRAY ARRAY[
    'projects','phases','buildings','units','customers','bookings',
    'contracts','installments','receipts','receipt_cheque_events','contract_templates'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS audit_change ON public.%I',table_name);
    EXECUTE format('CREATE TRIGGER audit_change AFTER INSERT OR UPDATE OR DELETE ON public.%I
      FOR EACH ROW EXECUTE FUNCTION app.audit_business_change()',table_name);
  END LOOP;
END $audit_triggers$;

-- Financial receipts and cheque events retain the immutability guards from migration 0011.
CREATE OR REPLACE FUNCTION public.prevent_audit_changes() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN
 RAISE EXCEPTION 'Audit trail is append-only' USING ERRCODE='42501';
END $$;
DROP TRIGGER IF EXISTS audit_logs_immutable ON public.audit_logs;
CREATE TRIGGER audit_logs_immutable BEFORE UPDATE OR DELETE ON public.audit_logs
FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_changes();
